using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Windows.Forms;
namespace LoopPedal {partial class Pedal {
 static IEnumerable<string> VstFiles(string directory){if(!Directory.Exists(directory))yield break;string[] files=null,folders=null;try{files=Directory.GetFiles(directory,"*.vst3");folders=Directory.GetDirectories(directory);}catch{}if(files!=null)foreach(var file in files)yield return file;if(folders!=null)foreach(var folder in folders){if(folder.EndsWith(".vst3",StringComparison.OrdinalIgnoreCase))yield return folder;else foreach(var file in VstFiles(folder))yield return file;}}
 static string[] InstalledVsts(){string common=Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFiles),local=Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);return VstFiles(Path.Combine(common,"VST3")).Concat(VstFiles(Path.Combine(local,"Programs/Common/VST3"))).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(Path.GetFileNameWithoutExtension).ToArray();}
 ContextMenuStrip lastVstMenu;
 VstRack[] trackedVstRacks=new VstRack[2];readonly List<Tuple<VstRack,DateTime>> retiredVstRacks=new List<Tuple<VstRack,DateTime>>();
 void RetireVstRack(VstRack rack){if(rack!=null)retiredVstRacks.Add(Tuple.Create(rack,DateTime.UtcNow.AddSeconds(2)));}
 void WatchVstRacks(){for(int bank=0;bank<2;bank++){var rack=loopers[bank].Fx.Plugins;if(!object.ReferenceEquals(rack,trackedVstRacks[bank])){RetireVstRack(trackedVstRacks[bank]);trackedVstRacks[bank]=rack;}}if(retiredVstRacks.Count==0)return;var active=new HashSet<VstInstance>();Action<VstRack> protect=r=>{if(r!=null)foreach(var slot in r.Slots)if(slot!=null&&slot.Instance!=null)active.Add(slot.Instance);};foreach(var bus in loopers)protect(bus.Fx.Plugins);var scenes=loopers[0].Scenes;if(scenes.Pending!=null)foreach(var bus in scenes.Pending.Banks)protect(bus.Fx.Plugins);if(scenes.Retiring!=null)foreach(var bus in scenes.Retiring)protect(bus.Fx.Plugins);for(int i=retiredVstRacks.Count-1;i>=0;i--){var item=retiredVstRacks[i];if(DateTime.UtcNow<item.Item2)continue;foreach(var slot in item.Item1.Slots)if(slot!=null&&slot.Instance!=null&&!active.Contains(slot.Instance))slot.Instance.Dispose();retiredVstRacks.RemoveAt(i);}}
 static void CloseVstEditors(VstRack rack){if(rack!=null)foreach(var slot in rack.Slots)if(slot!=null&&slot.Instance!=null&&slot.Instance.Editor!=null)slot.Instance.Editor.Close();}
 void ReplaceVst(int kind,string path,Action render){try{EnsureNotRecording();status.Text="Loading VST3…";status.Refresh();var fx=loopers[fxSendBank].Fx;CloseVstEditors(fx.Plugins);var rack=fx.Plugins==null?new VstRack():fx.Plugins.Copy();var slot=new VstSlot{Path=path,Name=Path.GetFileNameWithoutExtension(path)};rack.Slots[kind]=slot;rack.Prepare();if(slot.Instance==null)throw new InvalidOperationException(slot.Error);fx.Plugins=rack;status.Text=(fxSendBank==0?"A":"B")+" · "+slot.Name;render();}catch(Exception ex){status.Text=ex.Message;}}
 void VstMenu(Control anchor,int kind,Action render){var fx=loopers[fxSendBank].Fx;var menu=NewMenu();lastVstMenu=menu;var replace=Item(menu.Items,"Replace with VST3…");foreach(string path in InstalledVsts()){string file=path;Item(replace.DropDownItems,Path.GetFileNameWithoutExtension(file),()=>ReplaceVst(kind,file,render));}Item(replace.DropDownItems,"Browse .vst3 file…",()=>{using(var dialog=new OpenFileDialog{Filter="VST3 effect|*.vst3",InitialDirectory=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonProgramFiles),"VST3")})if(dialog.ShowDialog(this)==DialogResult.OK)ReplaceVst(kind,dialog.FileName,render);});Item(replace.DropDownItems,"Browse .vst3 bundle…",()=>{using(var dialog=new FolderBrowserDialog{Description="Select the .vst3 bundle folder",ShowNewFolderButton=false})if(dialog.ShowDialog(this)==DialogResult.OK)ReplaceVst(kind,dialog.SelectedPath,render);});var slot=fx.Plugins==null?null:fx.Plugins.Slots[kind];if(slot!=null){Item(menu.Items,"Pop out editor",()=>OpenVst(slot,render));Item(menu.Items,"Bypass plugin",()=>{slot.Bypass=!slot.Bypass;render();},slot.Bypass);Item(menu.Items,"Reload plugin",()=>{try{CloseVstEditors(fx.Plugins);var rack=fx.Plugins.Copy();rack.Prepare();fx.Plugins=rack;render();}catch(Exception ex){status.Text=ex.Message;}});Item(menu.Items,"Restore built-in effect",()=>{try{EnsureNotRecording();CloseVstEditors(fx.Plugins);var rack=fx.Plugins.Copy();rack.Slots[kind]=null;if(rack.HasPlugins){rack.Prepare();fx.Plugins=rack;}else fx.Plugins=null;render();}catch(Exception ex){status.Text=ex.Message;}});}menu.Show(anchor,new Point(0,anchor.Height));}
 void OpenVst(VstSlot slot,Action render){try{if(slot.Instance==null){slot.Prepare();if(slot.Instance==null)throw new InvalidOperationException(slot.Error);}slot.Instance.ShowEditor(this,()=>{slot.State=slot.Instance.Snapshot();render();});}catch(Exception ex){status.Text=ex.Message;}}
 void VstPanel(Panel editor,VstSlot slot,int kind,Action render){var panel=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=1,RowCount=2,Margin=Padding.Empty,Padding=new Padding(8),BackColor=Skin.Panel};panel.RowStyles.Add(new RowStyle(SizeType.Absolute,38));panel.RowStyles.Add(new RowStyle(SizeType.Percent,100));editor.Controls.Add(panel);var bar=new Panel{Dock=DockStyle.Fill,Margin=Padding.Empty};panel.Controls.Add(bar,0,0);var note=new Label{Text=(fxSendBank==0?"A":"B")+" · "+slot.Name,ForeColor=Skin.Mint,TextAlign=ContentAlignment.MiddleLeft,AutoEllipsis=true,Location=new Point(0,0),Size=new Size(320,28)};bar.Controls.Add(note);var bypass=(PadButton)Btn("BYPASS",()=>{slot.Bypass=!slot.Bypass;render();});bypass.Lit=slot.Bypass;bypass.Size=new Size(84,28);bar.Controls.Add(bypass);var pop=Btn("POP OUT",()=>OpenVst(slot,render));pop.Size=new Size(88,28);bar.Controls.Add(pop);var options=Btn("⋯",()=>VstMenu(bar,kind,render));options.Size=new Size(36,28);bar.Controls.Add(options);Action arrange=()=>{int x=Math.Max(0,bar.Width-218);note.Width=Math.Max(40,x-8);bypass.Location=new Point(x,0);pop.Location=new Point(x+90,0);options.Location=new Point(x+184,0);};bar.Resize+=(s,e)=>arrange();arrange();var view=new VstEditorView(slot,message=>{note.Text=(fxSendBank==0?"A":"B")+" · "+(message??slot.Name);});view.Name="VstEmbeddedEditor";view.Dock=DockStyle.Fill;view.Margin=Padding.Empty;panel.Controls.Add(view,0,1);}
}
sealed class VstEditorView:Panel {
 readonly VstSlot slot;readonly Panel surface=new Panel();readonly Action<string> status;bool attached,queued,fitting;string message="Loading plugin editor…";
 public VstEditorView(VstSlot plugin,Action<string> report){slot=plugin;status=report;BackColor=Skin.Ink;surface.BackColor=Skin.Ink;Controls.Add(surface);SetStyle(ControlStyles.OptimizedDoubleBuffer,true);}
 protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);QueueAttach();}
 protected override void OnVisibleChanged(EventArgs e){base.OnVisibleChanged(e);if(Visible)QueueAttach();}
 void QueueAttach(){if(queued||attached||!IsHandleCreated||IsDisposed)return;queued=true;BeginInvoke((Action)(()=>{queued=false;if(IsDisposed)return;try{if(slot.Instance==null){message=slot.Error??"Plugin unavailable";surface.Visible=false;Invalidate();return;}if(!slot.Instance.Embed(surface)){message="Editor is open in a separate window.";surface.Visible=false;Invalidate();return;}attached=true;surface.Visible=true;Fit();}catch(Exception ex){message=ex.Message;surface.Visible=false;if(status!=null)status(message);Invalidate();}}));}
 void Fit(){if(!attached||fitting||ClientSize.Width<50||ClientSize.Height<50||slot.Instance.Handle==IntPtr.Zero)return;fitting=true;try{int width,height;int fit=VstNative.av_editor_fit(slot.Instance.Handle,ClientSize.Width,ClientSize.Height,out width,out height);surface.SetBounds(Math.Max(0,(ClientSize.Width-width)/2),Math.Max(0,(ClientSize.Height-height)/2),width,height);if(status!=null)status(fit==2?"Editor needs more room · Pop out":null);}finally{fitting=false;}}
 protected override void OnResize(EventArgs e){base.OnResize(e);Fit();}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);if(!attached)Skin.Text(e.Graphics,message,Font,Skin.Muted,ClientRectangle,ContentAlignment.MiddleCenter);}
 protected override void Dispose(bool disposing){if(disposing&&slot.Instance!=null&&slot.Instance.Handle!=IntPtr.Zero)slot.Instance.DetachEmbedded(surface);base.Dispose(disposing);}
}
}
